  "aoc.terms.title": "Common terms in your aid offer",
  "aoc.terms.intro": "To compare aid offers side by side, you have to know what each line means. That's harder than it sounds, because schools don't use one standard format. Here are the terms you'll see most often.",
  "aoc.terms.coa.title": "Cost of attendance (COA)",
  "aoc.terms.coa.desc": "The school's estimate of what one academic year costs. It usually covers tuition and fees, housing and food, books and supplies, and transportation. It's an estimate, so what you actually spend may be higher or lower.",
  "aoc.terms.sai.title": "Student Aid Index (SAI)",
  "aoc.terms.sai.desc": "A number calculated from the information on your FAFSA. Schools and the federal government use it to decide how much aid you qualify for. It replaced the old Expected Family Contribution (EFC).",
  "aoc.terms.need.title": "Financial need",
  "aoc.terms.need.desc": "The gap between what school costs and what you can pay. The basic formula is the school's COA minus your SAI. Your SAI stays the same from school to school, but your need doesn't, because each school sets its own COA and some use their own formulas for school-funded aid. The same student can show very different need at two different schools.",
  "aoc.terms.workStudy.title": "Work-study",
  "aoc.terms.workStudy.desc": "A part-time job on or near campus that helps you earn money for school. Schools run the programs, and the federal government funds most of them. Not everyone qualifies. If you said you were interested on your FAFSA and you're eligible, your offer will list a work-study amount.",
  "aoc.terms.giftAid.title": "Gift aid",
  "aoc.terms.giftAid.desc": "Free money you don't pay back. It comes as grants and scholarships.",
  "aoc.terms.loans.title": "Student loans",
  "aoc.terms.loans.desc": "Money you borrow and repay with interest. Your offer will usually list federal loans. Private loans rarely show up in an aid offer, but a few schools include them.",
  "aoc.modal.title": "Email My Aid Offer Comparison",
