  "fmf.tier1.badge": "NIVEL 01 · MAYOR VALOR MONETARIO",
  "fmf.tier1.title": "Asistencias Académicas y Exenciones de Matrícula",
  "fmf.tier1.amount": "Valor: $25,000 – $75,000+ / año",
  "fmf.tier1.benefit": "Exención del 50% al 100% de Matrícula + Estipendio Mensual + Seguro Médico",
  "fmf.tier1.desc": "Las asistencias docentes (TA), de investigación (RA) y administrativas (GA) brindan exención directa de matrícula más un estipendio quincenal o mensual ($1,500–$3,800/mes) a cambio de 10 a 20 horas semanales de trabajo académico. Son el pilar para estudiar un posgrado sin deudas.",
  "fmf.tier1.how": "Cómo conseguirlo: Comunícate con el Coordinador de Posgrado de tu departamento antes de que se emitan las admisiones. Solicita confirmación por escrito de si tu paquete está garantizado por varios años.",
  "fmf.tier1.source": "Estándar oficial: Resolución del 15 de abril del Council of Graduate Schools (CGS) y catálogos institucionales.",
  "fmf.tier2.badge": "NIVEL 02 · MÉRITO E INVESTIGACIÓN",
  "fmf.tier2.title": "Becas de Excelencia Nacionales e Institucionales",
  "fmf.tier2.amount": "Valor: $30,000 – $53,000+ / año",
  "fmf.tier2.benefit": "Sin Obligación Laboral o Docente + Estipendio de Manutención + Subsidio Educativo",
  "fmf.tier2.desc": "Las 'fellowships' son distinciones por mérito que financian tus estudios sin requerir horas de docencia o laboratorio. Los programas federales y filantrópicos más prestigiosos pagan estipendios directamente al estudiante y asignaciones a la universidad.",
  "fmf.tier2.examples": "Programas insignia: NSF Graduate Research Fellowship Program (GRFP: $37,000 de estipendio + $16,000 de asignación educativa), NDSEG, Fundación Hertz, Programa Fulbright y Becas del Decano institucionales.",
  "fmf.tier2.how": "Cómo conseguirlo: Postula entre agosto y noviembre del año anterior. Es fundamental redactar declaraciones de propósito bien enfocadas y propuestas de investigación rigurosas.",
  "fmf.tier2.source": "Fuente oficial: National Science Foundation (nsfgrfp.org) y agencias federales patrocinadoras.",
  "fmf.tier3.badge": "NIVEL 03 · AYUDA POR NECESIDAD FINANCIERA",
  "fmf.tier3.title": "Subvenciones Federales, Estatales y Universitarias por Necesidad",
  "fmf.tier3.amount": "Valor: $1,000 – $15,000+ / año",
  "fmf.tier3.benefit": "Ayuda no reembolsable por necesidad · Cero obligación de devolución",
  "fmf.tier3.desc": "A diferencia del pregrado, los estudiantes de posgrado son clasificados automáticamente como independientes en el FAFSA—por lo que los ingresos parentales no se evalúan. Aunque las Becas Pell son para pregrado, puedes acceder a subvenciones TEACH (hasta $4,000/año para educadores elegibles), fondos estatales y subsidios institucionales.",
  "fmf.tier3.how": "Cómo conseguirlo: Envía tu FAFSA en StudentAid.gov en cuanto se abra la convocatoria. Consulta las fechas límite de prioridad de cada universidad, ya que los fondos limitados se agotan con rapidez.",
  "fmf.tier3.source": "Fuente oficial: Departamento de Educación de EE.UU. (StudentAid.gov) y juntas estatales de educación superior.",
  "fmf.tier4.badge": "NIVEL 04 · SECTOR PRIVADO Y PROFESIONAL",
  "fmf.tier4.title": "Becas de Asociaciones Profesionales y Fundaciones Privadas",
  "fmf.tier4.amount": "Valor: $500 – $20,000+ por beca",
  "fmf.tier4.benefit": "Fondos en Efectivo Directos · Acumulables para Manutención y Libros",
  "fmf.tier4.desc": "Miles de fundaciones sin fines de lucro, asociaciones profesionales y empresas ofrecen becas según tu especialidad académica, antecedentes o impacto comunitario. Muchas pueden aplicarse libremente a colegiatura o gastos personales.",
  "fmf.tier4.examples": "Patrocinadores clave: IEEE, American Bar Association (ABA), American Medical Association (AMA), AICPA, Society of Women Engineers y fundaciones comunitarias.",
  "fmf.tier4.how": "Cómo conseguirlo: Usa únicamente buscadores no comerciales verificados. Organiza un calendario con fechas de entrega, ensayos y cartas de recomendación.",
  "fmf.tier4.source": "Fuente oficial: Buscador CareerOneStop del Departamento de Trabajo de EE.UU.",
  "fmf.tier5.badge": "NIVEL 05 · ASISTENCIA DEL EMPLEADOR",
  "fmf.tier5.title": "Asistencia de Matrícula del Empleador y Beneficios del IRS § 127",
  "fmf.tier5.amount": "Valor: Hasta $5,250 / año libres de impuestos",
  "fmf.tier5.benefit": "Exento de Impuestos Federales y Retenciones de Nómina (Código IRS § 127)",
  "fmf.tier5.desc": "Conforme a la Sección 127 del Código del IRS, las empresas pueden aportar hasta $5,250 al año en asistencia educativa exenta de impuestos. Numerosas organizaciones ofrecen convenios corporativos con reembolsos de $10,000 a $25,000+ anuales.",
  "fmf.tier5.how": "Cómo conseguirlo: Consulta el portal de beneficios de tu empresa en 'Educational Assistance'. Revisa las calificaciones mínimas exigidas (usualmente calificación B o superior) y cláusulas de permanencia.",
  "fmf.tier5.source": "Fuente oficial: Internal Revenue Service (Publicación 970 del IRS, Sección 127).",
  "fmf.scam.tag": "PASO 02 · ALERTA AL CONSUMIDOR DE LA FTC",
  "fmf.scam.title": "Cuidado con las Estafas de Becas y Ayuda Financiera",
  "fmf.scam.desc": "La Comisión Federal de Comercio (FTC) advierte que existen servicios fraudulentos que se hacen pasar por entidades oficiales o registros de subvenciones. Recuerda esta regla de oro: las becas y la ayuda financiera legítimas nunca te cobran dinero.",
  "fmf.scam.flag1.title": "Tarifas de solicitud o procesamiento",
  "fmf.scam.flag1.desc": "Nunca pagues para postular, buscar o reclamar una beca. Si una empresa solicita un 'cargo administrativo' o 'depósito de trámite', es una estafa.",
  "fmf.scam.flag2.title": "Promesas de \"Dinero Garantizado\"",
  "fmf.scam.flag2.desc": "Ningún servicio privado puede garantizarte una beca o subsidio. Los comités de selección independientes toman todas las decisiones de adjudicación.",
  "fmf.scam.flag3.title": "Notificaciones de adjudicación no solicitadas",
  "fmf.scam.flag3.desc": "Si recibes mensajes diciendo que ganaste un premio al que nunca postulaste, ten cuidado. Nunca des tus números bancarios o tarjetas de crédito para 'liberar' fondos.",
  "fmf.scam.flag4.title": "Bases de datos \"exclusivas\" de pago",
  "fmf.scam.flag4.desc": "Quienes afirman tener acceso 'secreto' a miles de millones en subsidios no reclamados están engañando. Todas las oportunidades reales están en bases de datos públicas y gratuitas.",
  "fmf.scam.link": "Lee la guía oficial de la FTC contra estafas de becas en consumer.ftc.gov →",
  "fmf.tools.tag": "PASO 03 · SOLO HERRAMIENTAS GRATUITAS VERIFICADAS",
  "fmf.tools.title": "Buscadores Oficiales y No Comerciales",
  "fmf.tools.desc": "Siguiendo los estándares federales de protección al consumidor, solo enlazamos herramientas gratuitas mantenidas por agencias del gobierno y organizaciones verificadas sin fines de lucro. Cero comisiones de afiliados, cero intermediarios de pago.",
  "fmf.tool1.name": "Buscador de Becas CareerOneStop",
  "fmf.tool1.agency": "Departamento de Trabajo de EE.UU.",
  "fmf.tool1.desc": "Más de 8,000 becas y subsidios verificados. Filtra directamente por nivel de posgrado, especialidad académica y estado de residencia.",
  "fmf.tool1.cta": "Buscar en CareerOneStop.org →",
