  "aoc.terms.title": "Términos comunes en tu oferta de ayuda",
  "aoc.terms.intro": "Para comparar ofertas de ayuda lado a lado, debes saber qué significa cada línea. Es más difícil de lo que parece, porque las universidades no usan un formato estándar. Estos son los términos que verás con más frecuencia.",
  "aoc.terms.coa.title": "Costo de asistencia (COA)",
  "aoc.terms.coa.desc": "La estimación de la universidad sobre el costo de un año académico. Suele incluir matrícula y tarifas, alojamiento y alimentación, libros y suministros, y transporte. Es un estimado, por lo que lo que realmente gastes puede ser mayor o menor.",
  "aoc.terms.sai.title": "Índice de Ayuda Estudiantil (SAI)",
  "aoc.terms.sai.desc": "Un número calculado a partir de los datos de tu FAFSA. Las universidades y el gobierno federal lo usan para decidir a cuánta ayuda calificas. Reemplazó a la antigua Contribución Familiar Esperada (EFC).",
  "aoc.terms.need.title": "Necesidad financiera",
  "aoc.terms.need.desc": "La diferencia entre lo que cuesta estudiar y lo que puedes pagar. La fórmula básica es el COA de la escuela menos tu SAI. Tu SAI permanece igual de una universidad a otra, pero tu necesidad no, porque cada institución fija su propio COA y algunas usan fórmulas propias para ayuda institucional. El mismo estudiante puede reflejar necesidades muy distintas en dos universidades diferentes.",
  "aoc.terms.workStudy.title": "Trabajo y estudio (Work-study)",
  "aoc.terms.workStudy.desc": "Un empleo de medio tiempo en el campus o cerca de él para ayudarte a ganar dinero para estudiar. Las instituciones administran los programas y el gobierno federal financia la mayoría. No todos califican. Si indicaste interés en tu FAFSA y eres elegible, tu oferta incluirá un monto de trabajo y estudio.",
  "aoc.terms.giftAid.title": "Ayuda de regalo (Gift aid)",
  "aoc.terms.giftAid.desc": "Dinero gratuito que no tienes que devolver. Se presenta en forma de subvenciones y becas.",
  "aoc.terms.loans.title": "Préstamos estudiantiles",
  "aoc.terms.loans.desc": "Dinero que pides prestado y reembolsas con intereses. Tu oferta normalmente incluirá préstamos federales. Los préstamos privados rara vez aparecen en una carta de ayuda, pero algunas escuelas los incluyen.",
  "aoc.modal.title": "Enviar mi comparativa de ayuda por correo",
  "aoc.modal.desc": "Ingresa tu correo electrónico para guardar el resumen de tu comparativa y recibir una copia para tus registros.",
  "aoc.modal.nameLabel": "Tu nombre (opcional)",
  "aoc.modal.emailLabel": "Tu correo electrónico",
  "aoc.modal.emailPlaceholder": "tu@ejemplo.com",
