  "aoc.modal.successTitle": "¡Comparativa guardada!",
  "aoc.modal.successDesc": "Tu resumen de comparativa ha sido guardado. También puedes abrirlo en tu aplicación de correo para enviarlo a tu familia o asesor financiero.",
  "aoc.modal.openEmailBtn": "Abrir en aplicación de correo",
  "aoc.modal.printBtn": "Guardar como PDF / Imprimir",
  "aoc.modal.close": "Cerrar",
  "aoc.modal.error": "Por favor ingresa un correo electrónico válido.",
