  "ed.eyebrow": "Confianza y transparencia",
  "ed.h1": "Estándares editoriales y política de divulgación",
  "ed.sub":
    "Cómo decidimos qué publicar, cómo elegimos qué prestamistas mostrarte y exactamente cómo ganamos dinero. Nada de esto debería sorprenderte.",
  "ed.updated": "Revisado el 30 de julio de 2026",
  "ed.nav.editorial": "Estándares editoriales",
  "ed.nav.disclosure": "Política de divulgación",
  "ed.part1": "Primera parte",
  "ed.p1.h2": "Estándares editoriales",
  "ed.p1.lead":
    "Grad Navigator existe para explicar en lenguaje claro una parte confusa y cambiante del sistema de préstamos. Eso solo funciona si las explicaciones son exactas y están al día — así es exactamente cómo nos exigimos cumplirlo.",
  "ed.review.h3": "Cómo se revisa el contenido",
  "ed.review.p":
    "Cada explicación de este sitio se redacta y luego la revisa una persona identificada antes de publicarse — no solo se corrige la ortografía, sino que se coteja con la fuente real: normativa federal, divulgaciones de los prestamistas y studentaid.gov. Nada se publica sin el nombre de un revisor.",
  "ed.team1.role": "Contenido e investigación",
  "ed.team.name": "Equipo editorial",
  "ed.team1.p":
    "Redacta cada explicación directamente a partir de fuentes primarias — texto de las normas federales, hojas de tasas de los prestamistas y documentos de divulgación.",
  "ed.team2.role": "Revisión de exactitud",
  "ed.team2.p":
    "Coteja cada página publicada con el material fuente vigente antes y después de su publicación.",
  "ed.sourcing.h3": "Fuentes y citas",
  "ed.sourcing.p":
    "Enlazamos a la fuente primaria siempre que exista — studentaid.gov para las reglas federales y las divulgaciones de tasas publicadas por el propio prestamista para todo lo relacionado con comparaciones. Si no podemos verificar una cifra con una fuente primaria, no la publicamos.",
  "ed.current.h3": "Mantener el contenido al día",
  "ed.current.p":
    "Cada página lleva una fecha de \u201crevisado el\u201d. Las reglas de los préstamos de posgrado han cambiado de forma importante este año y probablemente vuelvan a cambiar — las páginas se revisan de forma periódica y de inmediato cuando conocemos un cambio normativo que las afecta.",
  "ed.corrections.h3": "Correcciones",
  "ed.corrections.p1":
    "Si algo en este sitio es incorrecto, queremos saberlo antes de que tomes una decisión costosa basada en ello. Las correcciones se hacen con prontitud y las correcciones importantes se señalan en la propia página en lugar de editarse en silencio.",
  "ed.corrections.p2.pre": "¿Notaste algo que no cuadra? ",
  "ed.corrections.link": "Contáctanos",
  "ed.corrections.p2.post": " y lo revisaremos.",
  "ed.independence.h3": "Independencia editorial",
  "ed.independence.p":
    "Nuestros prestamistas asociados no escriben, revisan ni aprueban nuestro contenido. Lo que decimos sobre cómo funciona una tasa, qué significa una comisión o si necesitas un codeudor se escribe igual, sea o no ese prestamista un socio.",
  "ed.part2": "Segunda parte",
  "ed.p2.h2": "Política de divulgación",
  "ed.p2.lead":
    "Este sitio es gratuito y genera ingresos como la mayoría de los sitios de comparación independientes: mediante relaciones de colaboración con prestamistas. Así funciona exactamente.",
  "ed.callout.strong": "Versión corta:",
  "ed.callout.p":
    " si te aprueban con un prestamista al que enlazamos, podríamos ganar una comisión. No te cuesta nada adicional y no cambia tu tasa ni cómo clasificamos a los prestamistas.",
  "ed.earn.h3": "Cómo ganamos dinero",
  "ed.earn.p":
    "Cuando haces clic hacia un prestamista desde este sitio y te aprueban un préstamo, ese prestamista puede pagarnos una comisión por referido. Esto es habitual en los sitios de comparación y es lo que nos permite mantener gratuitas todas las explicaciones, sin muro de pago ni correo electrónico obligatorio para navegar.",
  "ed.choose.h3": "Cómo elegimos qué prestamistas mostrar",
  "ed.choose.p":
    "Los prestamistas no pagan por aparecer y pagarnos más no los coloca más arriba en una comparación. Seleccionamos y priorizamos prestamistas según:",
  "ed.choose.li1":
    "Si sus tasas y condiciones son realmente competitivas para la situación del prestatario que trata la página",
  "ed.choose.li2":
    "La flexibilidad crediticia, sobre todo para prestatarios que puedan necesitar un codeudor",
  "ed.choose.li3":
    "Con qué claridad el prestamista divulga sus propias tasas, comisiones y criterios de elegibilidad",
  "ed.nochange.h3": "Lo que no cambia por nuestra relación con un prestamista",
  "ed.nochange.p":
    "Tu tasa de interés, tus probabilidades de aprobación y las condiciones de tu préstamo los define por completo el prestamista según tu solicitud. No podemos influir en nada de eso, y que sea socio nuestro nunca se traduce en una tasa mejor o peor para ti.",
  "ed.ads.h3": "Publicidad y contenido patrocinado",
  "ed.ads.p":
    "Cualquier contenido patrocinado, si alguna vez aparece, se identificará claramente como tal — nunca se mezclará con una explicación como si fuera contenido editorial independiente.",
  "ed.cta.h2": "¿Tienes una pregunta que esto no respondió?",
  "ed.cta.p": "Con gusto explicamos cualquier cosa sobre cómo funciona este sitio.",
  "ed.cta.btn": "Contáctanos →",

